-- GENERATED by `wfj generate` from data/gossip/gossip-96.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["9601f5bcafaa3d1b"] = { "Di cosa ti occupi esattamente, Rohan?", "." },
  ["96024ca6532d8a50"] = { "\"Magical Flows and How They Effect the World\", di Maginor Dumas. È quello che cercavo.", "." },
  ["96040fe2c0c66187"] = { "Nessuna traccia di Ol' Rustlocke, {name}?", "." },
  ["960566488689bc15"] = { "Credi che mi servano altre spille?", "." },
  ["9606325e9f3640e8"] = { "La tua conoscenza delle pozioni ha superato la mia, ma hai ancora molto da imparare. Sali le scale a sud-est e va' dal dottor Marsh. Ti insegnerà la vera soffere... ehm. È un Reietto che ti addestrerà ancora.", "." },
  ["960724e7369511cd"] = { "Ti prego, teletrasportami alla camera finale.", "." },
  ["961176df283e9fbe"] = { "Va' in fretta, {name}. Il mio destino è nelle tue mani.", "." },
  ["9615bf1b82dad619"] = { "La ⟦Alterac Valley=Valle d'Alterac⟧ è da anni la casa del ⟦Frostwolf Clan=Clan Lupi Bianchi⟧: non permetteremo ai nani e alla loro ⟦Alliance=Alleanza⟧ di invaderla! E così combattiamo!\n\nPer riconquistare Alterac, sconfiggi il loro generale, ⟦Vanndar Stormpike=Vanndar Piccatonante⟧, a Dun Baldar.\n\nPer l'⟦Horde=Orda⟧!", "." },
  ["9630f424a03a024b"] = { "La tua interferenza non sarà tollerata!", "." },
  ["96377ddbb57ded2a"] = { "Graham Van Talen, nel ⟦Rogues' Quarter=Quartiere dei Ladri⟧, sull'anello esterno di ⟦Undercity=Sepulcra⟧.", "." },
  ["96393e8715e7dbfc"] = { "La West Frostwolf Tower protegge la porta tra il ⟦Frostwolf Village=Villaggio dei Lupi Bianchi⟧ e la ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧.\n\nNon è controllata da nessuna delle due fazioni.", "." },
  ["96460c6377210008"] = { "Se avessi una moneta di rame per ogni tua impresa, sarei un coboldo ricco!", "." },
  ["9654f36796bf7315"] = { "Non ti racconto storie, verme. L'oscurità di questi oggetti potrebbe benissimo distruggerci entrambi. Ecco perché il prezzo è così alto. Se devo morire, morirò ricco.\n\nE non me ne importa uno sputo di gnoll di come muori tu, basta che tu faccia ciò che ti chiedo. Portami ciò che mi serve e ne avremo vantaggio entrambi... o moriremo, ma questo te l'ho già spiegato...", "." },
  ["9658e4fed8ef2e2c"] = { "Guerriero", "." },
  ["965e4c9f25e1ef2f"] = { "Sei luogotenenti controllano le difese della prima linea. Vanno distrutti per primi, e in fretta! Non possiamo rischiare che uno dei loro sacerdoti riporti in vita i luogotenenti caduti.\n\nSe tutti i luogotenenti verranno uccisi in rapida successione, il morale della prima linea vacillerà! Andrà in frantumi! Le loro truppe fuggiranno terrorizzate, lasciando i soldati rimasti senza rinforzi.", "." },
  ["966169ea44730040"] = { "Te lo farò sapere. È evidente che ti stai già mettendo in luce nelle nostre file, se sei <diventato/diventata> luogotenente così in fretta. Forse potrai tornare da me più tardi e avrò dei compiti per te. Il consiglio adora chi è esperto nelle arti arcane, ma i servitori di ogni genere sono sempre benvenuti, qualunque sia la loro professione.", "." },
  ["9670097c1261702a"] = { "Forse, ma se mi colpisse in testa saprei esattamente quale cannone usare per farlo saltare in mille pezzi!", "." },
  ["9673b2b515f97b57"] = { "Cavalcalupi, al ⟦Frost Dagger Pass=Passo di Lama del Gelo⟧!", "." },
  ["96785a1cdbd4898e"] = { "PER IL RE!", "." },
  ["9685684bc768cf7c"] = { "Se vogliamo proteggere la natura, dobbiamo abbracciarne la forza. E dobbiamo mostrare questa forza a chi vorrebbe fare del male alla terra.", "." },
  ["9687dd8490e9826f"] = { "%s si siede.", "." },
  ["96881cc4edba4838"] = { "Negli ultimi anni ho visto accadere cose terribili ai mezzorsi: sono stati vittime su molti fronti. Ma non mi è chiaro che fine abbia fatto questa tribù. Sono stati corrotti dalla stessa piaga che ha colpito ⟦Felwood=Vilbosco⟧? O forse sono semplicemente furiosi per ciò che è accaduto al loro popolo, un tempo pacifico, e ora cercano di difendersi. In ogni caso, la maggior parte di loro sembra ostile verso chi entra nella zona.", "." },
  ["968b687d92d2c2cd"] = { "Con l'apprendimento, {name}, arriva la maestria.", "." },
  ["9690b0152546b80d"] = { "⟦Sharptalon=Grinfiafina⟧, la più possente di tutte le bestie della Caccia di ⟦Ashenvale=Valtetra⟧, è libero di vagare per concessione dei sedicenti guardiani di queste terre, gli elfi della notte. ⟦Sharptalon=Grinfiafina⟧ va a caccia di prede a sud di qui, e si diletta a fare a pezzi i viaggiatori ignari e sprovveduti.\n\nAbbattere una bestia simile sarebbe il più grande dei bottini, {name}. Ti auguro buona fortuna nella caccia!", "." },
  ["96977971b401ac91"] = { "Non dimenticare di comprare rinfreschi e souvenir!", "." },
  ["969b268ca889719c"] = { "Il nostro bisogno di aiuto nel ⟦Arathi Basin=Bacino d'Arathi⟧ è più grande di quanto si possa immaginare, {name}. Ma lo sono anche l'onore e la reputazione che si possono ottenere lì in questo momento di bisogno. Ti imploro di cercare il maestro di battaglia del ⟦Arathi Basin=Bacino d'Arathi⟧ in questa città.", "." },
  ["96a20ec6b4b146e1"] = { "Dammi il contratto.", "." },
  ["96a54621cff021fa"] = { "Sì, signore!", "." },
  ["96b78eb3413f9f4a"] = { "La schiena mi sta uccidendo.", "." },
  ["96b7ade5f54b1d41"] = { "Ucciderti essere facile.", "." },
  ["96c0673ae1b34209"] = { "Di loto purpureo siamo pieni fino all'orlo, {class}. Chiedi a qualcun altro se gli serve il tuo aiuto, e lasciami ai miei studi. Non c'è tempo da perdere!", "." },
  ["96c805a7cd796dee"] = { "Cosa? Qualcuno ha detto birra? Non cominciate a versare le pinte senza il vecchio Torren!", "." },
  ["96cede1d919a08f9"] = { "Le ⟦Sentinels=Sentinelle⟧ fanno ciò che possono qui a ⟦Ashenvale=Valtetra⟧, ma è grazie a {race} come te che abbiamo guadagnato il terreno che abbiamo.", "." },
  ["96cf7b6b46dc0180"] = { "Sono quasi pronta a mandarti a svolgere gli altri compiti. Hai già riempito la borraccia?\n\nSo quanto possono essere protettivi i verrospini. Anche una fonte d'acqua così piccola per loro è un tesoro immenso. Fanno grandi banchetti quando cade anche la più leggera pioggia sulle ⟦Barrens=Savane⟧. L'acqua è sacra per la loro specie perché è così scarsa. Capisci?", "." },
  ["96d324eadb9b70dd"] = { "Ci farà la pelle se ci beccano!", "." },
  ["96d4b6aee16a97d9"] = { "Hai una certa abilità nel forgiare armi, <ragazzo/ragazza>, davvero notevole. Ora prendi un martello e vediamo se sai forgiare un'arma vera.", "." },
  ["96da25d81aebd9e6"] = { "Un ⟦Ash'ari Crystal=Cristallo Ash'ari⟧ è stato ripristinato!", "." },
  ["96dc0c6ef479d122"] = { "La pazienza è la virtù più grande della terra. La terra è testimone del ciclo di tutte le cose: le montagne che diventano deserti, i fiumi che diventano canyon. La terra è il più ostinato e saggio di tutti gli elementi, e non tollera l'impazienza.\n\nLa terra ora ti chiama perché si avvicina un tempo di conflitto. Quando tornerai da me dopo aver avuto successo, sarai molto più vicin<o/a> a essere complet<o/a>.\n\nAltri invidieranno la tua saggezza e ti odieranno per la loro ignoranza.", "." },
  ["96dca08e561f1ca2"] = { "Faresti meglio ad andartene, <ragazzo/ragazza>. Il mio animale qui ha fame, e gli piace il tuo odore.", "." },
  ["96e132442580bdc8"] = { "Basta chiacchiere. Sto morendo di fame! Ora porta quel tuo guscio impolverato in mare e procura qualcosa da mettere sotto i denti alla mamma.", "." },
  ["96f4959e9920440a"] = { "Non si possono insegnare trucchi nuovi a un cane vecchio. Almeno così mi hanno detto una volta. Per tua fortuna, ho scoperto che non è vero.\n\nTuttavia, i famigli tendono a diventare resistenti alla tecnica, e mi serve sempre più cibo per tenerli contenti. Questo significa che mi dovrai più soldi ogni volta che faccio disimparare le abilità allo stesso famiglio.\n\nAllora, vuoi che cominci a fargli disimparare le abilità?", "." },
  ["96f52fc9b71fc1bd"] = { "L'⟦Horde=Orda⟧ ha preso la fucina!", "." },
  ["96fa8ca1f413e251"] = { "Sembra che siamo nei guai. Occhi aperti, arrivano!", "." },
})
